 1	`timescale 1ns / 1ps
 2	
 3	module ALU(
 4	    input[31:0] A, B,
 5	    input[3:0] Control,
 6	    output[31:0] res,
 7	    output zero, overflow
 8	);
 9	
10	    parameter ALU_ADD  = 4'b0001;
11	    parameter ALU_SUB  = 4'b0010;
12	    parameter ALU_AND  = 4'b0011;
13	    parameter ALU_OR   = 4'b0100;
14	    parameter ALU_XOR  = 4'b0101;
15	    parameter ALU_SLL  = 4'b0110;
16	    parameter ALU_SRL  = 4'b0111;
17	    parameter ALU_SLT  = 4'b1000;
18	    parameter ALU_SLTU = 4'b1001;
19	    parameter ALU_SRA  = 4'b1010;
20	    parameter ALU_Ap4  = 4'b1011;
21	    parameter ALU_Bout = 4'b1100;
22	
23	    // 实现：根据 Control 选择运算，并生成 zero / overflow 标志
24	    // The ALU must support: ADD, SUB, AND, OR, XOR, SLL, SRL, SLT, SLTU, SRA, A+4, B-passthrough
25	    // Use the Control input to select which operation to perform.
26	    // zero should be 1 when res is all zeros.
27	    // overflow should be set for signed ADD/SUB overflow.
28	
29	    // 各运算结果（移位只使用 B 的低 5 位）
30	    wire[31:0] res_ADD  = A + B;
31	    wire[31:0] res_SUB  = A - B;
32	    wire[31:0] res_AND  = A & B;
33	    wire[31:0] res_OR   = A | B;
34	    wire[31:0] res_XOR  = A ^ B;
35	    wire[31:0] res_SLL  = A << B[4:0];
36	    wire[31:0] res_SRL  = A >> B[4:0];
37	    wire[31:0] res_SRA  = $signed(A) >>> B[4:0];
38	    wire       res_lt   = $signed(A) < $signed(B);   // 有符号比较
39	    wire       res_ltu  = A < B;                     // 无符号比较
40	    wire[31:0] res_SLT  = {31'b0, res_lt};
41	    wire[31:0] res_SLTU = {31'b0, res_ltu};
42	    wire[31:0] res_Ap4  = A + 32'd4;                 // JAL/JALR: PC+4
43	    wire[31:0] res_Bout = B;                         // LUI: 直接输出 B
44	
45	    wire is_ADD  = Control == ALU_ADD ;
46	    wire is_SUB  = Control == ALU_SUB ;
47	    wire is_AND  = Control == ALU_AND ;
48	    wire is_OR   = Control == ALU_OR  ;
49	    wire is_XOR  = Control == ALU_XOR ;
50	    wire is_SLL  = Control == ALU_SLL ;
51	    wire is_SRL  = Control == ALU_SRL ;
52	    wire is_SLT  = Control == ALU_SLT ;
53	    wire is_SLTU = Control == ALU_SLTU;
54	    wire is_SRA  = Control == ALU_SRA ;
55	    wire is_Ap4  = Control == ALU_Ap4 ;
56	    wire is_Bout = Control == ALU_Bout;
57	
58	    assign res = {32{is_ADD }} & res_ADD  |
59	                 {32{is_SUB }} & res_SUB  |
60	                 {32{is_AND }} & res_AND  |
61	                 {32{is_OR  }} & res_OR   |
62	                 {32{is_XOR }} & res_XOR  |
63	                 {32{is_SLL }} & res_SLL  |
64	                 {32{is_SRL }} & res_SRL  |
65	                 {32{is_SLT }} & res_SLT  |
66	                 {32{is_SLTU}} & res_SLTU |
67	                 {32{is_SRA }} & res_SRA  |
68	                 {32{is_Ap4 }} & res_Ap4  |
69	                 {32{is_Bout}} & res_Bout ;
70	
71	    assign zero = ~(|res);
72	
73	    // 只有 ADD/SUB 才产生有符号溢出
74	    assign overflow = is_ADD & (~(A[31] ^ B[31]) & (res_ADD[31] ^ A[31])) |
75	                      is_SUB & ( (A[31] ^ B[31]) & (res_SUB[31] ^ A[31])) ;
76	
77	endmodule
